//! 🕸️ Controlled graph identity, exact positions, ordered ports and typed properties.
use super::{SemioGraphSnapshot,SemioGraphNode,SemioGraphEdge,SemioGraphPort,SemioGraphPortKind,GraphNodeId,GraphEdgeId,SemioValueEntry,SemioPoint2,STDIO_SEMIOGRAPH_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::schema::snapshot::native_decoding as native;
use crate::standards::v1::subsets::value::schema::snapshot::native_decoding as values;
use semio_framework_value::native_decoding::NativeDecodeControl;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(super) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioGraphSnapshot,String>{native::decode(payload,STDIO_SEMIOGRAPH_DOCUMENT_SCHEMA,control,binary,document)}
fn kind(tag:u8)->Result<SemioGraphPortKind,String>{Ok(match tag{0=>SemioGraphPortKind::In,1=>SemioGraphPortKind::Out,2=>SemioGraphPortKind::InOut,_=>return Err("invalid Semio native port kind".into())})}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioGraphSnapshot,String>{
 let mut entities=0;native::entities(&mut entities,1,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|error|error.to_string())?!=1{return Err("unsupported Semio graph native format".into())}let schema=native::text(&mut reader,control)?;let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut nodes=native::Owned::new(control.allocate_vec::<SemioGraphNode>(count)?);
 control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{
 let id=GraphNodeId::new(native::text(&mut reader,control)?);let kind=native::text(&mut reader,control)?;let label=native::text(&mut reader,control)?;let position=SemioPoint2{x:reader.read_f64_le().map_err(|error|error.to_string())?,y:reader.read_f64_le().map_err(|error|error.to_string())?};let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut ports=control.allocate_vec::<SemioGraphPort>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let name=native::text(&mut reader,control)?;let kind=self::kind(reader.read_u8().map_err(|error|error.to_string())?)?;ports.push(SemioGraphPort{name,kind});control.step()?;}Ok::<_,String>(())})?;
 let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;if count>limits.max_rows.saturating_sub(entities){return Err("Semio graph native properties exceed remaining row limit".into())}let mut properties=native::Owned::new(control.allocate_vec::<SemioValueEntry>(count)?);control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let key=native::text(&mut reader,control)?;let value=values::value_binary(&mut reader,control,limits,&mut entities)?;properties.get_mut().push(SemioValueEntry{key,value});control.step()?;}Ok::<_,String>(())})?;nodes.get_mut().push(SemioGraphNode{id,kind,label,position,ports,properties:properties.take()});control.step()?;
 }Ok::<_,String>(())})?;
 let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut edges=control.allocate_vec::<SemioGraphEdge>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let id=GraphEdgeId::new(native::text(&mut reader,control)?);let source=GraphNodeId::new(native::text(&mut reader,control)?);let target=GraphNodeId::new(native::text(&mut reader,control)?);let kind=native::text(&mut reader,control)?;let label=native::text(&mut reader,control)?;edges.push(SemioGraphEdge{id,source,target,kind,label});control.step()?;}Ok::<_,String>(())})?;
 if reader.remaining()!=0{return Err("Semio graph native trailing bytes".into())}Ok(SemioGraphSnapshot{schema,nodes:nodes.take(),edges})
}
fn number(value:&str,control:&mut NativeDecodeControl<'_>)->Result<f64,String>{let value=native::hex_text(value,control)?;native::float(&value,control)}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioGraphSnapshot,String>{
 let mut entities=0;native::entities(&mut entities,1,limits)?;let fields=native::fields(body,["schema","nodes","edges"],control)?;let schema=native::hex_text(fields[0].ok_or("Semio graph native schema missing")?,control)?;let mut items=native::Items::new(fields[1].unwrap_or("[]"))?;let count=items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut nodes=native::Owned::new(control.allocate_vec::<SemioGraphNode>(count)?);
 control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=items.next(control)?{
 let[id,kind,label,x,y,port_fields,property_fields]=native::record(item,control)?;let id=GraphNodeId::new(native::hex_text(id,control)?);let kind=native::hex_text(kind,control)?;let label=native::hex_text(label,control)?;let position=SemioPoint2{x:number(x,control)?,y:number(y,control)?};let mut port_items=native::Items::new(port_fields)?;let count=port_items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut ports=control.allocate_vec::<SemioGraphPort>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=port_items.next(control)?{let[name,tag]=native::record(item,control)?;let name=native::hex_text(name,control)?;let tag=match tag{"i"=>0,"o"=>1,"x"=>2,_=>return Err("invalid Semio native port kind".into())};ports.push(SemioGraphPort{name,kind:self::kind(tag)?});control.step()?;}Ok::<_,String>(())})?;
 let mut property_items=native::Items::new(property_fields)?;let count=property_items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;if count>limits.max_rows.saturating_sub(entities){return Err("Semio graph native properties exceed remaining row limit".into())}let mut properties=native::Owned::new(control.allocate_vec::<SemioValueEntry>(count)?);control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=property_items.next(control)?{let(key,value)=item.split_once(':').ok_or("Semio graph native property requires colon")?;let key=native::hex_text(key,control)?;let value=values::value_text(value,control,limits,&mut entities)?;properties.get_mut().push(SemioValueEntry{key,value});control.step()?;}Ok::<_,String>(())})?;nodes.get_mut().push(SemioGraphNode{id,kind,label,position,ports,properties:properties.take()});control.step()?;
 }Ok::<_,String>(())})?;
 let mut items=native::Items::new(fields[2].unwrap_or("[]"))?;let count=items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut edges=control.allocate_vec::<SemioGraphEdge>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=items.next(control)?{let[id,source,target,kind,label]=native::record(item,control)?;let id=GraphEdgeId::new(native::hex_text(id,control)?);let source=GraphNodeId::new(native::hex_text(source,control)?);let target=GraphNodeId::new(native::hex_text(target,control)?);let kind=native::hex_text(kind,control)?;let label=native::hex_text(label,control)?;edges.push(SemioGraphEdge{id,source,target,kind,label});control.step()?;}Ok::<_,String>(())})?;
 Ok(SemioGraphSnapshot{schema,nodes:nodes.take(),edges})
}
